39|type SkinListener = () => void;
40|
41|const listeners = new Set<SkinListener>();
42|let storageHooked = false;
43|
44|function notify(): void {
45|  for (const cb of listeners) cb();
46|}
47|
48|function hookStorage(): void {
49|  if (storageHooked) return;
50|  try {
51|    if (typeof window === "undefined" || typeof window.addEventListener !== "function") return;
52|    window.addEventListener("storage", (e) => {
53|      if (e.key !== SKIN_KEY || !isSkinId(e.newValue)) return;
54|      try {
55|        document.documentElement.dataset.skin = e.newValue;
56|      } catch {
57|        return;
58|      }
59|      notify();
60|    });
61|    storageHooked = true;
62|  } catch {
63|    // No window (server render, tests): subscriptions stay in-process.
64|  }
65|}
