1|// The current skin has one runtime owner: this module. Every skin-dependent
2|// surface (icons, read-along highlight, Picture this animations, image style,
3|// button animations) reads from here via getSkin/subscribe or useSkin (see
4|// app/use-skin.ts), or via CSS keyed on `html[data-skin]`. Nothing else may
5|// write data-skin: setSkin/cycleSkin are the only writers, called by the
6|// future home cycling button / skin switcher.
7|export const SKINS = ["engraving", "watercolor", "ink", "comic", "anime-ghibli"] as const;
8|export type SkinId = (typeof SKINS)[number];
9|// Denslow fits Oz; the default until a skin switcher exists.
10|export const DEFAULT_SKIN: SkinId = "engraving";
11|
12|export function isSkinId(v: unknown): v is SkinId {
13|  return (SKINS as readonly unknown[]).includes(v);
14|}
15|
16|export const SKIN_KEY = "lectoria.skin";
17|
18|// Pure: a valid `?skin=` in search wins, else a valid stored value, else the
19|// default. Anything else is ignored. The inline script below must stay in sync
20|// with this (it cannot import this module).
21|export function initialSkin(stored: unknown, search?: string): SkinId {
22|  try {
23|    if (typeof search === "string" && search) {
24|      const q = new URLSearchParams(search).get("skin");
25|      if (isSkinId(q)) return q;
26|    }
27|  } catch {
28|    // Malformed search string: fall through to the stored value.
29|  }
30|  return isSkinId(stored) ? stored : DEFAULT_SKIN;
31|}
32|
33|// Pre-first-paint inline script, rendered in layout.tsx next to THEME_SCRIPT.
34|// Applies the same rule as initialSkin to document.documentElement data-skin;
35|// try/catch falls back to the default. The `?skin=` override applies to that
36|// load only and is NOT written to storage.
37|export const SKIN_SCRIPT = `(function(){try{var l=${JSON.stringify(SKINS)};var d=${JSON.stringify(DEFAULT_SKIN)};var q=null;try{q=new URLSearchParams(location.search).get("skin");}catch(e){}if(l.indexOf(q)>=0){document.documentElement.dataset.skin=q;return;}var s=null;try{s=localStorage.getItem(${JSON.stringify(SKIN_KEY)});}catch(e){}document.documentElement.dataset.skin=l.indexOf(s)>=0?s:d;}catch(e){try{document.documentElement.dataset.skin=${JSON.stringify(DEFAULT_SKIN)};}catch(_){}}})();`;
38|
39|type SkinListener = () => void;
40|
41|const listeners = new Set<SkinListener>();
42|let storageHooked = false;
43|
44|function notify(): void {
45|  for (const cb of listeners) cb();
46|}
47|
48|function hookStorage(): void {
49|  if (storageHooked) return;
50|  try {
51|    if (typeof window === "undefined" || typeof window.addEventListener !== "function") return;
52|    window.addEventListener("storage", (e) => {
53|      if (e.key !== SKIN_KEY || !isSkinId(e.newValue)) return;
54|      try {
55|        document.documentElement.dataset.skin = e.newValue;
56|      } catch {
57|        return;
58|      }
59|      notify();
60|    });
61|    storageHooked = true;
62|  } catch {
63|    // No window (server render, tests): subscriptions stay in-process.
64|  }
65|}
66|
67|// Reads the live data-skin on documentElement (DEFAULT_SKIN on the server or
68|// when invalid). Client-safe: never throws.
69|export function getSkin(): SkinId {
70|  try {
71|    if (typeof document === "undefined") return DEFAULT_SKIN;
72|    const v: unknown = document.documentElement?.dataset?.skin;
73|    return isSkinId(v) ? v : DEFAULT_SKIN;
74|  } catch {
75|    return DEFAULT_SKIN;
76|  }
77|}
78|
79|// Sets data-skin, persists to SKIN_KEY (try/catch), notifies subscribers.
80|export function setSkin(s: SkinId): void {
81|  try {
82|    document.documentElement.dataset.skin = s;
83|  } catch {
84|    // No DOM (server render, tests): still persist and notify below.
85|  }
86|  try {
87|    localStorage.setItem(SKIN_KEY, s);
88|  } catch {
89|    // Private mode / denied storage: the live value still applies.
90|  }
91|  notify();
92|}
93|
94|export function subscribe(cb: SkinListener): () => void {
95|  listeners.add(cb);
96|  hookStorage();
97|  return () => {
98|    listeners.delete(cb);
99|  };
100|}
101|
102|// Next skin in SKINS order, applied. For the home cycling button.
103|export function cycleSkin(): SkinId {
104|  const next = SKINS[(SKINS.indexOf(getSkin()) + 1) % SKINS.length]!;
105|  setSkin(next);
106|  return next;
107|}

